T["All: Never stand in front of or behind Onyxia (breath/tail).\nPhase 2 from 65%: dodge fireballs, kill whelps at once.\nPhase 3 from 40%: fear - grounding totem and fear ward ready.\nTank: Onyxia with her back to the wall, head away from the raid.\nTank: phase 3 take aggro back at once.\nHealer: tank first, spread out in phase 2.\nDPS: go full only after 3 sunders from the tank.\nDPS: phase 2: whelps before Onyxia."] = "Tutti: mai davanti o dietro Onyxia (soffio/coda).\nFase 2 dal 65%: schivare le palle di fuoco, abbattere subito i cuccioli.\nFase 3 dal 40%: paura - Totem del Radicamento e Protezione dalla Paura pronti.\nDifensore: Onyxia con la schiena al muro, testa lontana dall'incursione.\nDifensore: in fase 3 riprendere subito l'aggro.\nGuaritori: il difensore ha la priorità, in fase 2 stare sparpagliati.\nDPS: attaccare a pieno solo dopo 3 attacchi alle spalle del difensore.\nDPS: fase 2: cuccioli prima di Onyxia."
T["All: swarm target: run out.\nTank: infernal tank off to the side.\nHealer: remove sleep where possible.\nDPS: ignore infernals, everything on the boss."] = "Tutti: bersaglio dello sciame: uscire.\nDifensore: difensore degli Infernali in disparte.\nGuaritori: rimuovere il sonno dove possibile.\nDPS: ignorare gli Infernali, tutto sul boss."
T["All: leave Death and Decay at once.\nTank: hold the middle, don't move during frost nova.\nHealer: heal the ice block target fast.\nDPS: ranged spread wide (icebolt chain)."] = "Tutti: uscire subito da Morte e Decomposizione.\nDifensore: tenere il centro, non muoversi con Nova di Gelo.\nGuaritori: curare in fretta il bersaglio nel blocco di ghiaccio.\nDPS: a distanza ben sparpagliati (catena di Dardo di Ghiaccio)."
