T["Automatic: every 10 minutes and on logout Oasis stores a snapshot in the saved variables (WTF/Account/<account>/SavedVariables/Oasis.lua). The program Tools/oasis_export.py reads the file, turns it into JSON and can send it to your web page. Addons have no internet access - this is the safe way."] = "Automatico: Oasis salva ogni 10 minuti e al logout un'istantanea nelle Variabili salvate (WTF/Account/<Konto>/SavedVariables/Oasis.lua). Il programma Tools/oasis_export.py legge il file, lo converte in JSON e può inviarlo alla vostra interfaccia web. Gli addon non hanno accesso a Internet - questo è il modo sicuro."
