T["You'll find the download in our Discord."] = "Trovi il download nel nostro Discord."
T["You can also drag the button around the minimap."] = "Puoi anche spostare il pulsante direttamente sulla minimappa col mouse."
T["The raid simulator is only available in the developer version."] = "Il simulatore d'incursione esiste solo nella versione sviluppatore."
T["Only leadership, raid leaders and raid assistants may edit the raid plan."] = "Il piano d'incursione può essere modificato da gestione gilda, capi incursione e assistenti."
T["WoW can't show this class's talent tree here. You can copy the export string below."] = "WoW non può mostrare qui l'albero dei talenti di questa classe. Il testo d'esportazione si può copiare sotto."
T["Delete the whole history with %s? Saved messages are deleted too."] = "Eliminare l'intera cronologia con %s? Anche i messaggi salvati vanno persi."
T["The order goes to every crafter with this recipe - whoever has time takes it."] = "L'ordine va a tutti gli artigiani con questa ricetta - chi ha tempo lo accetta."
T["The order is withdrawn for everyone."] = "L'ordine viene ritirato per tutti."
T["The customer is told it's ready."] = "Il committente viene avvisato che è pronto."
T["The requester will be notified."] = "Il committente viene avvisato."
T["The bazaar is empty"] = "Il bazar è vuoto"
T["The Barrens chat with its sayings"] = "La chat di Barrens con le sue battute"
T["The client delivers no skills right now - wait a moment after logging in."] = "Il client al momento non fornisce abilità - attendi un attimo dopo l'accesso."
T["The dungeon compass: which dungeon fits, what drops there for you."] = "La bussola delle spedizioni: quale spedizione è adatta, cosa cade lì per te."
T["The enemy was not in front of you. It was behind you. The whole time."] = "Il nemico non era davanti a te. Era dietro di te. Tutto il tempo."
T["The group leader can make you an assistant."] = "Il capogruppo può renderti assistente."
T["The fight was locked at first and was recorded afterwards."] = "Il combattimento era inizialmente bloccato ed è stato elaborato in seguito."
T["The button can no longer be dragged"] = "Il pulsante non può più essere spostato col mouse"
T["The link applies to all officers."] = "Il link vale per tutti i capi."
T["The market uses prices from the AH addon Midas. As soon as you or a guild member scans the AH with Midas, this page unlocks."] = "Il mercato usa i prezzi dell'addon AH Midas. Appena tu o qualcuno della gilda scansiona la casa d'aste con Midas, questa pagina si sblocca."
T["Play-time tracking is off. Turn it on and Oasis learns a little more every evening."] = "La registrazione degli orari di gioco è disattiva. Attivala e Oasis impara ogni sera."
T["The Oasis rank is Oasis's guild rank - it rises by playing together, helping, crafting, events and badges."] = "Il grado Oasis è il grado di gilda di Oasis - sale giocando insieme, aiutando, con artigianato, eventi e distintivi."
T["This person's online sound is muted for you."] = "Il suono online di questa persona è disattivato per te."
T["The Oasis window border glows in your colour"] = "Il bordo della finestra di Oasis brilla del tuo colore"
T["The ring shows who has nothing open."] = "L'anello mostra chi è senza punti aperti."
T["The Stone Eater"] = "Il Divoratore di Pietre"
T["That date is in the past."] = "L'evento è nel passato."
T["Details"] = "Dettagli"
T["Tue"] = "Mar"
T["Diagnostics and sync"] = "Diagnosi e sincronizzazione"
T["Diamond"] = "Diamante"
T["Diamond = Banish (Warlock)"] = "Diamante = Esilio (stregone)"
T["Visited the bank. Just counting real quick."] = "Visitata la banca. Diamo una ricontata."
T["The ban list is empty."] = "La lista dei bannati è vuota."
T["The chat input was touched by Oasis (e.g. 'Whisper' button), then /target was typed."] = "L'input della chat era stato toccato da Oasis (es. pulsante 'Sussurra'), poi è stato digitato /target."
T["The chat input was touched by Oasis (e.g. 'Whisper' button), then a /cast command was typed there."] = "L'input della chat era stato toccato da Oasis (es. pulsante 'Sussurra'), poi vi è stato digitato un comando /cast."
T["The chat input was touched by Oasis, then /focus was typed."] = "L'input della chat era stato toccato da Oasis, poi è stato digitato /focus."
T["The chat input was touched by Oasis, then a spell command was typed."] = "L'input della chat era stato toccato da Oasis, poi è stato digitato un comando d'incantesimo."
T["Dungeon maps have no coordinates. Click here, then on the spot where you stand. Done at two distant spots, Oasis shows you and your group on the map - for the whole guild."] = "Le mappe delle spedizioni non hanno coordinate. Clicca qui, poi sul punto della mappa dove ti trovi ora. Fatto in due punti lontani, Oasis mostra te e il tuo gruppo sulla mappa - per tutta la gilda."
T["The guild will be notified"] = "La gilda viene avvisata"
T["The guild can see whom you react to. Default: off"] = "La gilda vede a chi rispondi. Predefinito: disattivo"
T["The guild sees your fire on the map for %d minutes."] = "La gilda vede il tuo fuoco per %d minuti sulla mappa."
T["The guild sees your achievements in the chronicle"] = "La gilda vede nella cronaca ciò che hai raggiunto"
T["The guild isn't looking for anything from this dungeon."] = "La gilda al momento non cerca nulla da questa spedizione."
T["Your guild doesn't award loot points yet - your values appear once the raid leaders start a raid."] = "La gilda non assegna ancora punti bottino - i tuoi valori appaiono appena il capo incursione avvia un'incursione."
T["The guild bank hasn't been read yet"] = "La banca di gilda non è ancora stata letta"
T["The guild leadership names raid leaders and assistants under Crown > Modules > Raids & Loot (by name or from a guild rank). In a running raid, the raid leader and assistants count too."] = "La gestione gilda nomina capi incursione e assistenti in Corona > Moduli > Incursioni & bottino (nomi o da grado di gilda). Nell'incursione in corso contano anche capo incursione e assistenti."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader and assistants count too."] = "La gestione gilda nomina i capi incursione in Corona > Moduli > Incursioni & bottino. Nell'incursione in corso contano anche capo incursione e assistenti."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "La gestione gilda nomina i capi incursione in Corona > Moduli > Incursioni & bottino. Nell'incursione in corso conta anche il capo incursione."
T["The guild leadership only allows group searches from a higher rank."] = "La gestione gilda consente ricerche di gruppo solo da un grado più alto."
T["The guild leadership only allows polls from a higher rank."] = "La gestione gilda consente sondaggi solo da un grado più alto."
T["The guild leadership has disabled the partner search."] = "La gestione gilda ha disattivato la ricerca compagni."
T["The guild leadership has disabled open invites - challenge someone directly."] = "La gestione gilda ha disattivato gli inviti aperti - sfida qualcuno direttamente."
T["The guild leadership sets which ranks may do this under Crown > Modules."] = "La gestione gilda stabilisce in Corona > Moduli quali gradi possono farlo."
T["WoW's guild finder helps - neutral, no ads."] = "La ricerca gilde di WoW aiuta a trovare - neutrale, senza pubblicità."
T["Only the guild master sets the limit. Rank 1 = guild master."] = "Il limite lo stabilisce solo il maestro di gilda. Grado 1 = maestro di gilda."
T["The buttons put the command into the chat line - it only runs when you press Enter."] = "I pulsanti scrivono il comando nella riga di chat - viene eseguito solo con Invio."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window (not in combat - there Esc belongs to the game)."] = "Le scorciatoie sono anche nei Tasti di WoW sotto AddOns > Oasis. Esc chiude la finestra di Oasis (non in combattimento - lì Esc appartiene al gioco)."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window as long as you last clicked into it."] = "Le scorciatoie sono anche nei Tasti di WoW sotto AddOns > Oasis. Esc chiude la finestra di Oasis, se ci hai cliccato per ultima."
T["The bar rolls up out of view; move the mouse to the top edge and it comes down (only when docked at the top)"] = "La barra scorre via verso l'alto; porta il mouse al bordo superiore e scende (solo se agganciata in alto)"
T["The reservation line only appears while you are in a group or raid"] = "La riga delle prenotazioni appare solo se sei in un gruppo o in un'incursione"
T["The Scale of the Sands"] = "I Guardiani delle Sabbie"
T["Opened the world map. Where was north again?"] = "Aperta la mappa del mondo. Dov'era di nuovo il nord?"
T["The real bar above shows every change instantly"] = "La barra vera in alto mostra subito ogni modifica"
T["The first 20 stamina give 1 health each, every further point 10."] = "I primi 20 di Tempra danno 1 ciascuno, ogni punto in più 10 salute."
