T["Who"] = "Chi"
T["Who sends data that others reject (no permission, forged author, made-up entries). An unmodified Oasis practically never does this - a hint, not proof."] = "Chi invia dati rifiutati dagli altri (senza permessi, autore falsificato, voci inventate). Un Oasis non modificato non lo fa praticamente mai - un indizio, non una prova."
T["Anyone who registers interest appears in a matching slot. Once there is an event, sign up directly on its card."] = "Chi segnala interesse appare qui in un posto adatto. Se c'è un evento, ti iscrivi direttamente sulla mappa."
T["Who in the guild has the item on their wishlist"] = "Chi nella gilda ha l'oggetto nella lista desideri"
T["Who sees this section in the navigation (leadership always sees everything)"] = "Chi vede la sezione nella navigazione (la guida della gilda vede sempre tutto)"
T["Who left the guild or was removed. If someone returns, Oasis notifies guild management."] = "Chi ha lasciato la gilda o è stato rimosso. Se qualcuno torna, Oasis lo segnala alla guida della gilda."
T["Who sees the crown at the top. Without rights it is grey and only opens a preview."] = "Chi vede la corona in alto. Senza permessi è grigia e apre solo un'anteprima."
T["Who may pin a message at the top of guild chat"] = "Chi può fissare un messaggio in cima alla chat di gilda"
T["Who can invite is not known yet - log in once with your main and Oasis will remember the guild leadership."] = "Chi può invitare non è ancora noto - accedi una volta con il tuo main, poi Oasis memorizza la guida della gilda."
