T["Who could join?"] = "Chi potrebbe venire?"
T["Whoever shows up often and has received little gets first pick on 'Need'. Part of the points decays every week."] = "Chi c'è spesso e ha ricevuto poco ha la precedenza su 'Necessità'. Ogni settimana una parte dei punti scade."
T["Anyone who signs up with a fitting role is invited to your group right away."] = "Chi si propone con il ruolo adatto viene invitato subito nel tuo gruppo."
T["Who stands where with which faction? Close to the goal, farm together, progress this week"] = "Chi sta dove con quale fazione? Vicino all'obiettivo, farmare insieme, progresso di questa settimana"
T["Who deals, heals and takes the most?"] = "Chi infligge di più, cura di più, incassa di più?"
T["The guild master decides who belongs to the leadership under Crown > Guild."] = "Chi fa parte della guida della gilda lo decide il capogilda in Corona > Gilda."
T["Stats"] = "Valori"
T["stats do nothing for your role"] = "I valori non servono al tuo ruolo"
T["stats for info only"] = "Valori solo informativi"
T["Stats, yearbook, daily goal, records and adventures of your character."] = "Valori, annuario, obiettivo giornaliero, record e avventure del tuo personaggio."
T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "Valori: +cure, intelletto, spirito, rigen. mana;Arma: bastone o arma a una mano + mano secondaria con cure;Cure: Rinvigorimento e Ricrescita in anticipo, Tocco Curativo per colpi grandi;Suggerimento: Innervazione per il mana, Rinascita per i guaritori caduti"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "Valori: +cure, intelletto, critico magico (Illuminazione restituisce mana), rigen. mana;Arma: arma a una mano + mano secondaria/scudo con cure;Cure: Lampo di Luce per danni piccoli, Luce Sacra (rango basso) per colpi grandi;Suggerimento: distribuisci benedizioni, Protezione Divina se vieni attaccato"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "Valori: +cure, rigen. mana (MP5), intelletto - lo spirito serve poco;Arma: arma a una mano + scudo con cure;Cure: Catena di Guarigione per i gruppi, Onda Curativa (rango basso) per il tank;Suggerimento: piazza il Totem della Fonte di Mana, Scudo di Terra sul tank"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "Valori: +cure, spirito (Meditazione: rigenerazione anche lanciando), intelletto, rigen. mana;Arma: bastone o arma a una mano + mano secondaria con cure, bacchetta;Cure: Rinnovamento e Parola del Potere: Scudo in anticipo, Cura Superiore (rango basso) per il tank;Suggerimento: Preghiera di Guarigione per il gruppo, Svanire con aggro"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "Valori: armatura (la Forma d'Orso la moltiplica), tempra, agilità (schivata + armatura);Arma: irrilevante per il danno - contano solo i valori (bastone/arma ad asta con tempra);Rotazione: Maciullare, Fendente per i gruppi, Ruggito Demoralizzante;Suggerimento: forza per più minaccia, Infuriare all'inizio"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "Valori: forza (1 punto = 2 PA), agilità (PA + critico), critico, colpire fino a +9 %;Arma: irrilevante per il danno - contano solo i valori;Rotazione: Graffio/Lacerazione per punti combo, poi Morso Feroce;Suggerimento: powershift (rientrare in forma) per energia, balza fuori dalla furtività"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "Valori: forza (1 punto = 2 PA), critico (attiva Raffica = colpi più rapidi), colpire fino a +9 %;Arma: arma a due mani lenta - Furia del Vento colpisce per colpo, quindi più lenta = più danno;Rotazione: Arma Furia del Vento, Assalto Tempestoso, Scossa di Terra;Suggerimento: Totem della Forza della Terra e Totem Furia del Vento per il gruppo"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "Valori: forza (1 punto = 2 PA), critico, colpire fino a +9 %;Arma: arma a due mani lenta - Sigillo e Giudizio agiscono per colpo;Rotazione: Sigillo della Rettitudine/del Comando, Giudizio, rinnova il sigillo;Suggerimento: Consacrazione solo con mana sufficiente, Benedizione della Potenza per te"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "Valori: colpire fino a +9 %, agilità (1 PA, circa 29 = 1 % critico), PA, critico;Arma: combattimento = mano secondaria veloce, mano principale lenta (Colpo Sinistro); pugnali per Pugnalata;Rotazione: accumula punti combo, mantieni Affettare, poi Sventramento;Suggerimento: con due armi i colpi normali mancano più spesso - colpire è la cosa più importante"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "Valori: colpire fino a +9 %, agilità (2 PA a distanza, circa 53 = 1 % critico), PA, intelletto;Arma: arma a distanza lenta (molto danno per colpo), arma da mischia con valori;Rotazione: Marchio del Cacciatore, Tiro Automatico, Tiro Mirato/Tiro Multiplo in mezzo;Suggerimento: nutri il famiglio e tienilo felice, Trappola Congelante (quadrato) come controllo"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "Valori: colpire fino a +9 %, forza (1 punto = 2 PA), critico (circa 20 agilità = 1 %);Arma: arma a due mani lenta (Colpo Mortale, Colpo Eroico agiscono per colpo);Rotazione: accumula ira, Colpo Mortale / Sete di Sangue, Turbine, ira in eccesso in Colpo Eroico;Suggerimento: Grido di Battaglia prima del combattimento, Esecuzione sotto il 20 % di vita"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "Valori: difesa (440 = immune ai critici dei boss al 60), tempra, armatura, blocco con scudo;Arma: arma a una mano + scudo, arma veloce = più ira;Rotazione: Colpo di Scudo/Vendetta, Squarcia Armatura sul bersaglio, Colpo Eroico con molta ira;Suggerimento: colpire aiuta affinché Provocazione e abilità non manchino"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "Valori: difesa, tempra, armatura, poi danni magici per più minaccia;Arma: arma a una mano (meglio con danni magici) + scudo;Rotazione: Furia Giusta attiva, Consacrazione per i gruppi, mantieni Scudo Sacro;Suggerimento: il mana scarseggia - porta Sigillo della Saggezza o intelletto"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "Valori: danni magici, critico magico (Focus Elementale risparmia mana), intelletto, rigen. mana;Arma: arma a una mano + scudo/mano secondaria con danni magici;Rotazione: spamma Fulmine, Catena di Fulmini sui gruppi, Scossa di Fiamma;Suggerimento: colpire magico fino a +16 % in incursione, Totem della Fonte di Mana contro il mana vuoto"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "Valori: danni magici, critico magico, intelletto, colpire magico fino a +16 % in incursione;Arma: bastone o arma a una mano + mano secondaria con danni magici;Rotazione: Fuoco Lunare + Sciame di Insetti, poi Ira o Fuoco Stellare;Suggerimento: Innervazione su di te quando il mana scarseggia"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "Valori: danni magici, colpire magico fino a +16 % (incursione), tempra, intelletto;Arma: bastone o pugnale + mano secondaria con danni magici, bacchetta per il mana residuo;Rotazione: Corruzione + maledizione, poi Dardo d'Ombra; Prelievo di Vita invece di bere;Suggerimento: la tempra vale doppio (Prelievo di Vita, Ombra del Vuoto/Legame d'Anima)"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "Valori: danni magici, colpire magico fino a +16 % (incursione), spirito per il mana;Arma: bastone o arma a una mano + mano secondaria con danni magici;Rotazione: Parola d'Ombra: Dolore, Assalto Mentale, Flagello Mentale;Suggerimento: Forma d'Ombra sempre attiva, Abbraccio Vampirico cura il gruppo"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "Valori: danni magici, poi colpire magico fino a +16 % (boss d'incursione), intelletto, critico magico;Arma: bastone con danni magici, più una bacchetta per il mana residuo;Rotazione: spamma Dardo di Gelo o Palla di Fuoco, Evocazione con mana vuoto;Livellare: intelletto e spirito = meno pause, in gruppo usa Pecora (luna)"
T["rated as"] = "Punteggio"
T["Resistances, consumables, durability and keys for the next raid"] = "Resistenze, consumabili, durabilità e chiavi per il prossimo evento"
T["Like Blizzard's windows: black with a gold frame"] = "Come la finestra Blizzard: nero con bordo dorato"
