T["1.  Keep the combat log on (Settings > Areas > Combat board, on by default).\n2.  After playing, double-click ImportCrits.bat in the Oasis folder.\n3.  /reload in game - your highest crit shows here and is shared with the guild."] = "1.  Tieni attivo il registro di combattimento (Impostazioni > Aree > Classifica combattimento, attivo di base).\n2.  Dopo aver giocato, fai doppio clic su ImportCrits.bat nella cartella Oasis.\n3.  /reload in gioco - il tuo critico più alto appare qui e viene condiviso con la gilda."
