T["Active members below the officer ranks appear in the 'Promotion' list after this many days in the same rank. 0 = off."] = "I membri attivi sotto i gradi da ufficiale compaiono nella lista 'Promozione' dopo tanti giorni nello stesso grado. 0 = off."
T["Current zone first"] = "Prima la zona attuale"
T["All areas, grouped by topic: guild, playing together, raid, trade, fun. Click a heading to collapse its group."] = "Tutte le aree, raggruppate per tema: gilda, giocare insieme, incursione, commercio, divertimento. Clicca un titolo per chiudere il gruppo."
T["Expand all zones"] = "Espandi tutte le zone"
T["Collapse all zones"] = "Comprimi tutte le zone"
T["All members with rank, level and Oasis version. Right-click a row: change rank."] = "Tutti i membri con grado, livello e versione di Oasis. Clic destro su una riga: cambia grado."
T["All fonts under the SIL Open Font License 1.1"] = "Tutti i caratteri sotto SIL Open Font License 1.1"
T["All: Burning Adrenaline: run out of the raid AT ONCE (you are about to die).\nAll: Full resources at the start - use everything.\nTank: Set a tank order (Adrenaline on the tank).\nDD: Not in front of or behind the dragon."] = "All: Burning Adrenaline: correte SUBITO fuori dall'incursione (state per morire).\nAll: Risorse piene all'inizio - usate tutto.\nTank: Stabilite l'ordine dei tank (Adrenaline sul tank).\nDD: Non davanti né dietro al drago."
T["All: Do not let the 8 Firesworn die near the raid (explosion).\nTank: Each add tank pulls their Firesworn away, warlocks banish.\nHealer: Dispel, keep an eye on the add tanks.\nDD: Garr first, adds only when called."] = "All: Non fate morire gli 8 Firesworn vicino all'incursione (esplosione).\nTank: Ogni tank degli add porta via il suo Firesworn, gli stregoni esiliano.\nHealer: Dissolvete, occhio ai tank degli add.\nDD: Prima Garr, gli add solo su ordine."
T["All: Tank the two Core Ragers away from the boss, do not kill them.\nTank: Swap the Golemagg tank when Magma Splash stacks too high.\nDD: Only on Golemagg."] = "All: Tankate i due Core Rager lontano dal boss, non uccideteli.\nTank: Cambiate il tank di Golemagg quando Magma Splash si accumula troppo.\nDD: Solo su Golemagg."
T["All: The 4 priests first, they heal each other.\nTank: Keep Sulfuron and the priests apart.\nDD: Interrupt! Stop the priests' Dark Mending."] = "All: Prima i 4 sacerdoti, si curano a vicenda.\nTank: Tenete separati Sulfuron e i sacerdoti.\nDD: Interrompete! Fermate Dark Mending dei sacerdoti."
T["All: Fire protection! Wrath of Ragnaros knocks melee back - then get back in.\nAll: Sons phase (after 3 min or when he submerges): kill all Sons of Flame.\nTank: Second tank ready when the first is knocked away.\nHealer: Spread out, ranged not too close (Lava Burst).\nDD: Melee: keep mana under control, ranged keep your distance."] = "All: Protezione dal fuoco! Wrath of Ragnaros respinge la mischia - poi tornate sotto.\nAll: Fase dei Figli (dopo 3 min o quando si immerge): uccidete tutti i Figli della Fiamma.\nTank: Secondo tank pronto quando il primo viene respinto.\nHealer: Sparsi, a distanza non troppo vicini (Lava Burst).\nDD: Mischia: mana sotto controllo, a distanza state lontani."
T["All: Flame Buffet stacks - ranged behind pillars to let it drop.\nTank: Two tanks behind pillars, Wing Buffet knocks back.\nDD: Onyxia Scale Cloak required."] = "All: Flame Buffet si accumula - a distanza dietro le colonne per farlo svanire.\nTank: Due tank dietro le colonne, Wing Buffet respinge.\nDD: Mantello di Scaglie di Onyxia obbligatorio."
T["All: Remove Gehennas' Curse (reduced healing) at once.\nAll: Get out of the Rain of Fire.\nTank: Tank the two Flamewakers apart.\nDD: Flamewakers first, then Gehennas."] = "All: Rimuovete subito Gehennas' Curse (cure ridotte).\nAll: Uscite da Pioggia di Fuoco.\nTank: Tankate separati i due Flamewaker.\nDD: Prima i Flamewaker, poi Gehennas."
T["All: Remove Lucifron's Curse and Impending Doom at once (mages/druids, priests/paladins).\nTank: Tank the two guards apart - mind control!\nHealer: Spread out, dispel mind-controlled players.\nDD: Guards first, then Lucifron."] = "All: Rimuovete subito Lucifron's Curse e Impending Doom (maghi/druidi, sacerdoti/paladini).\nTank: Tankate separate le due guardie - controllo mentale!\nHealer: State sparsi, dissolvete i giocatori sotto controllo mentale.\nDD: Prima le guardie, poi Lucifron."
T["All: Living Bomb: run out of the raid AT ONCE!\nAll: Inferno - away from the boss, dispel Ignite Mana.\nTank: Hold the middle, step out briefly on Inferno.\nDD: Melee back off on Inferno."] = "All: Bomba Vivente: correte SUBITO fuori dall'incursione!\nAll: Inferno - via dal boss, dissolvete Ignite Mana.\nTank: Tenete il centro, uscite un attimo durante Inferno.\nDD: Mischia indietro durante Inferno."
T["All: Watch the guards' magic reflection/damage shield - stop damage then.\nTank: One guard per tank, mages sheep the elite guards.\nDD: Healer guards (Flamewaker Healer) first."] = "All: Occhio al riflesso magico/scudo di danno delle guardie - allora fermate i danni.\nTank: Una guardia per tank, i maghi trasformano in pecora le guardie élite.\nDD: Prima le guardie guaritrici (Flamewaker Healer)."
T["All: Never stand in front of or behind Onyxia (breath and tail sweep).\nAll: Phase 2 (65%): dodge fireballs, stay out of the cave entrances.\nAll: Phase 3 (40%): fear - Fear Ward/Tremor Totem ready, avoid the lava cracks.\nTank: Onyxia sideways at the wall, head away from the raid.\nTank: Phase 2: pick up the whelps. Phase 3: get aggro back at once.\nHealer: Tank has priority, spread out in phase 2.\nDD: Wait for 3 attacks of the tank. Phase 2: whelps first."] = "All: Mai davanti o dietro a Onyxia (soffio e colpo di coda).\nAll: Fase 2 (65%): schivate le palle di fuoco, fuori dagli ingressi delle grotte.\nAll: Fase 3 (40%): paura - Fear Ward/Totem del Tremore pronti, evitate le crepe di lava.\nTank: Onyxia di lato contro il muro, testa lontana dall'incursione.\nTank: Fase 2: raccogliete i cuccioli. Fase 3: riprendete subito l'aggro.\nHealer: Il tank ha la priorità, in fase 2 state sparsi.\nDD: Aspettate 3 attacchi del tank. Fase 2: prima i cuccioli."
T["All: Panic - Fear Ward/Tremor Totem, hunters: Tranquilizing Shot on Frenzy.\nAll: Get out of the lava fire on the ground.\nTank: Magmadar with his back to the raid.\nDD: Ranged spread out at the back."] = "All: Panico - Fear Ward/Totem del Tremore, cacciatori: Tiro Tranquillizzante su Frenesia.\nAll: Uscite dal fuoco di lava a terra.\nTank: Magmadar di spalle all'incursione.\nDD: A distanza sparsi in fondo."
T["All: Phase 1: dragonkin from both sides, watch the class calls.\nAll: Phase 3 (20%): the skeletons rise again - kill them again.\nTank: Nefarian at the wall, fear - Fear Ward.\nHealer: Class call for priests: healing hurts - be careful.\nDD: Hunters/warriors: watch the class calls (weapons gone, stance)."] = "All: Fase 1: dragonidi da entrambi i lati, occhio ai richiami di classe.\nAll: Fase 3 (20%): gli scheletri risorgono - uccideteli di nuovo.\nTank: Nefarian contro il muro, paura - Fear Ward.\nHealer: Richiamo di classe per i sacerdoti: le cure fanno danno - attenti.\nDD: Cacciatori/guerrieri: occhio ai richiami di classe (armi via, postura)."
T["All: Phase 1: destroy the eggs (mind control via the orb), pick up the adds.\nAll: After all eggs: boss in the room - Fire Nova.\nTank: Gather the adds at the stairs.\nDD: Mages and dragonkin first."] = "All: Fase 1: distruggete le uova (controllo mentale tramite il globo), prendete gli add.\nAll: Dopo tutte le uova: boss nella stanza - Fire Nova.\nTank: Radunate gli add alle scale.\nDD: Prima maghi e dragonidi."
T["All: Frenzy - hunters: Tranquilizing Shot.\nTank: Two tanks, watch Wing Buffet.\nDD: Onyxia Scale Cloak required."] = "All: Frenesia - cacciatori: Tiro Tranquillizzante.\nTank: Due tank, occhio a Wing Buffet.\nDD: Mantello di Scaglie di Onyxia obbligatorio."
T["All: Shadow of Ebonroc heals the boss - the tank with the debuff swaps.\nTank: Two tanks swap on Shadow.\nDD: Onyxia Scale Cloak required."] = "All: Shadow of Ebonroc cura il boss - il tank con il debuff fa cambio.\nTank: Due tank si scambiano con Shadow.\nDD: Mantello di Scaglie di Onyxia obbligatorio."
T["All: Knockback - stand against the wall.\nTank: Two tanks, aggro is split by Knock Away.\nDD: Mortal Strike on the tank: healers be prepared."] = "All: Contraccolpo - mettetevi contro il muro.\nTank: Due tank, l'aggro viene diviso da Knock Away.\nDD: Assalto Mortale sul tank: guaritori pronti."
T["All: He teleports - whoever has aggro, do not run away.\nAll: Remove Shazzrah's Curse, Arcane Explosion: melee keep your distance.\nTank: Get back on him right after every blink.\nHealer: Dispel (Deaden Magic)."] = "All: Si teletrasporta - chi ha l'aggro non scappi.\nAll: Rimuovete Shazzrah's Curse, Esplosione Arcana: mischia a distanza.\nTank: Tornategli addosso subito dopo ogni traslazione.\nHealer: Dissolvete (Deaden Magic)."
T["All: Two of the five breath types per week - avoid the breath behind the corner.\nAll: Hourglass Sand for the Bronze affliction.\nTank: Tank at the gate, raid behind the corner.\nDD: Tranquilizing Shot on Frenzy."] = "All: Due dei cinque tipi di soffio a settimana - evitate il soffio dietro l'angolo.\nAll: Hourglass Sand per l'afflizione di bronzo.\nTank: Tankate al cancello, incursione dietro l'angolo.\nDD: Tiro Tranquillizzante su Frenesia."
T["Hold Alt: all stats and scoring details. Shift: Blizzard comparison."] = "Tieni Alt: tutti i valori e la valutazione. Maiusc: confronto Blizzard."
T["Release Alt: compact view. Shift: Blizzard comparison."] = "Rilascia Alt: vista compatta. Maiusc: confronto Blizzard."
