T["That was just luck! Again!"] = "Solo fortuna! Ancora!"
T["That's it. You can find the tour again any time under Settings > Status or with /oa rundgang."] = "Tutto qui. Ritrovi il tour quando vuoi in Impostazioni > Stato o con /oa rundgang."
