T["You can find the download in the guild's Discord."] = "Trovi il download nel Discord della gilda."
T["The client does not let Oasis enable combat logging - please type /combatlog yourself."] = "Il client non permette a Oasis di attivare il registro di combattimento - digita tu /combatlog."
T["The content of the selected area. The overview shows who is online, what is coming up and what is new."] = "Il contenuto dell'area scelta. La panoramica mostra chi è online, cosa è in programma e cosa c'è di nuovo."
T["The minimap button or /oa opens Oasis. The dash at the top right turns the window into a slim bar."] = "Il pulsante della minimappa o /oa apre Oasis. Con il trattino in alto a destra la finestra diventa una barra sottile."
T["The officer channel (/o) with history - only for ranks with officer chat permission."] = "Il canale ufficiali (/o) con cronologia - solo per i gradi con permesso di chat ufficiali."
T["The yellow bar on the left of the list marks this."] = "Lo indica la barra gialla a sinistra nella lista."
T["Close details"] = "Chiudi dettagli"
T["Clear default sound for online notices"] = "Suono predefinito più chiaro per gli avvisi online"
T["Character statistics are unavailable in this client."] = "Le statistiche del personaggio non sono disponibili in questo client."
T["Guild leadership has muted sound effects for you."] = "La direzione della gilda ti ha bloccato gli effetti sonori."
T["The bar is there from login and stays - the X on the window only closes the window."] = "La barra c'è dall'accesso e resta - la X sulla finestra chiude solo la finestra."
T["The percentage compares the item's score for your role, not your total damage. Effects are estimates."] = "La percentuale confronta il punteggio dell'oggetto per il tuo ruolo, non il tuo danno totale. Gli effetti sono stime."
T["The statistic currently provides no readable value."] = "La statistica al momento non fornisce un valore leggibile."
T["Your guild's hub. In 30 seconds you will know your way around - here is what matters."] = "Il centro della vostra gilda. In 30 secondi saprai orientarti - ecco l'essenziale."
