T["The full license texts are in the Oasis folder: CREDITS.txt, LICENSE and LICENSE-MIT.txt."] = "I testi completi delle licenze sono nella cartella Oasis: CREDITS.txt, LICENSE e LICENSE-MIT.txt."
T["These guild ranks (0 = guild master) may vote in the loot council."] = "Questi gradi di gilda (0 = capogilda) possono votare nel consiglio del bottino."
